<?php
session_start();
require_once __DIR__ . '/../includes/cms.php';
$db = stac_cms_db();
if (!$db) { http_response_code(503); exit('CMS database is not configured. Copy includes/cms-config.example.php to includes/cms-config.php and add your Hostinger MySQL details.'); }
$db->exec('CREATE TABLE IF NOT EXISTS cms_admin (id TINYINT UNSIGNED PRIMARY KEY, password_hash VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
$db->exec('CREATE TABLE IF NOT EXISTS cms_pages (page VARCHAR(190) PRIMARY KEY, content MEDIUMTEXT NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
$hasAdmin = (bool)$db->query('SELECT COUNT(*) FROM cms_admin')->fetchColumn();
if (isset($_GET['logout'])) { $_SESSION = []; session_destroy(); header('Location: ./'); exit; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!hash_equals($_SESSION['csrf'] ?? '', $_POST['csrf'] ?? '')) { http_response_code(403); exit('Invalid request. Refresh and try again.'); }
    if (!$hasAdmin && isset($_POST['new_password'])) {
        if (strlen($_POST['new_password']) < 12) $error = 'Choose a password with at least 12 characters.';
        else { $q = $db->prepare('INSERT INTO cms_admin (id, password_hash) VALUES (1, ?)'); $q->execute([password_hash($_POST['new_password'], PASSWORD_DEFAULT)]); $hasAdmin = true; $_SESSION['stac_cms_logged_in'] = true; }
    } elseif (empty($_SESSION['stac_cms_logged_in']) && isset($_POST['password'])) {
        $hash = $db->query('SELECT password_hash FROM cms_admin WHERE id = 1')->fetchColumn();
        if ($hash && password_verify($_POST['password'], $hash)) { session_regenerate_id(true); $_SESSION['stac_cms_logged_in'] = true; }
        else $error = 'Incorrect password.';
    }
}
$_SESSION['csrf'] ??= bin2hex(random_bytes(32));
$pageNames = stac_cms_editable_pages();
$selected = in_array($_GET['page'] ?? '', $pageNames, true) ? $_GET['page'] : 'index.php';
?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>STAC Site Editor</title>
<style>
*{box-sizing:border-box}body{font:16px/1.5 system-ui,sans-serif;background:#edf2f7;color:#182b43;margin:0}.wrap{max-width:1440px;margin:0 auto;padding:24px}.top{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}h1{margin:0;font-size:25px;line-height:1.2}.top a,a{color:#123b70}.editor{display:grid;grid-template-columns:270px minmax(0,1fr);gap:18px;align-items:start}.panel,.preview-panel{background:white;border:1px solid #d8e1ea;border-radius:10px}.panel{padding:18px;position:sticky;top:16px}.preview-panel{padding:12px}.label{display:block;font-weight:650;margin:0 0 7px}.steps{padding:0 0 0 22px;margin:18px 0;color:#344b62}.steps li{padding:0 0 12px 4px}.steps b{color:#182b43}.help{padding:12px;border-radius:7px;background:#edf5fc;color:#344b62;font-size:14px}.toolbar{display:grid;gap:10px;margin-top:14px}.toolbar button,button{font:inherit;font-weight:600;padding:11px 13px;border:1px solid #b9c8d7;border-radius:6px;background:#fff;color:#173b62;cursor:pointer}.toolbar button:hover,button:hover{background:#eff5fb}.toolbar button:focus-visible,button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #78aee4;outline-offset:2px}.toolbar button:disabled{opacity:.55;cursor:not-allowed}.toolbar .primary{background:#123b70;color:white;border-color:#123b70}.toolbar .primary:hover{background:#0d2d57}.toolbar .primary:disabled{opacity:.55}.tools{display:flex;gap:6px}.tools button{flex:1}.toolbar select,select{font:inherit;padding:11px;border:1px solid #b9c8d7;border-radius:6px;width:100%;background:white}.hint{color:#516273;font-size:14px;margin:4px 4px 10px}.status{display:block;min-height:24px;margin-top:10px;font-weight:600;color:#23633d}.status.dirty{color:#855500}.status.error{color:#a3231b}iframe{display:block;width:100%;height:calc(100vh - 150px);min-height:600px;border:1px solid #cbd5df;border-radius:6px;background:white}.login input{font:inherit;padding:11px;border:1px solid #cbd5df;border-radius:6px}.login{max-width:460px}.login label{display:block;font-weight:650;margin:18px 0 7px}.notice{padding:12px;background:#e8f4ff;margin:16px 0}.notice.error{background:#fff0ef}@media(max-width:850px){.wrap{padding:14px}.editor{grid-template-columns:1fr}.panel{position:static}.steps{display:grid;grid-template-columns:1fr 1fr;gap:4px 18px}.toolbar{grid-template-columns:1fr 1fr}.toolbar .page-field{grid-column:1/-1}iframe{height:72vh;min-height:480px}}@media(max-width:520px){.steps{display:block}.toolbar{grid-template-columns:1fr}.toolbar .page-field{grid-column:auto}.preview-panel{padding:6px}iframe{min-height:420px}}
</style><div class="wrap"><div class="top"><h1>STAC Website Editor</h1><?php if (!empty($_SESSION['stac_cms_logged_in'])): ?><span><a href="images.php?page=<?= rawurlencode($selected) ?>">Manage images</a> · <a href="?logout=1">Log out</a></span><?php endif; ?></div>
<?php if (empty($_SESSION['stac_cms_logged_in'])): ?>
<p><?= $hasAdmin ? 'Enter your admin password.' : 'Create the owner password. It will be stored securely as a hash in the Hostinger database.' ?></p><?php if (!empty($error)): ?><p class="notice error"><?= htmlspecialchars($error) ?></p><?php endif; ?>
<form class="login" method="post"><input type="hidden" name="csrf" value="<?= htmlspecialchars($_SESSION['csrf']) ?>"><label><?= $hasAdmin ? 'Password' : 'Create password (12+ characters)' ?></label><input type="password" name="<?= $hasAdmin ? 'password' : 'new_password' ?>" required minlength="<?= $hasAdmin ? 1 : 12 ?>" autocomplete="<?= $hasAdmin ? 'current-password' : 'new-password' ?>"><button><?= $hasAdmin ? 'Log in' : 'Set admin password' ?></button></form>
<?php else: ?>
<div class="editor"><aside class="panel"><label class="label" for="page">1. Choose a page</label><select id="page" aria-label="Choose page"><?php foreach ($pageNames as $p): ?><option value="<?= htmlspecialchars($p) ?>" <?= $p === $selected ? 'selected' : '' ?>><?= htmlspecialchars(match($p) { 'index.php' => 'Home page', 'apply-to-kingster.php' => 'Apply Now', 'give-to-kingster.php' => 'Support Us', default => ucwords(str_replace(['-', '.php'], [' ', ''], $p)) }) ?></option><?php endforeach; ?></select>
<ol class="steps"><li><b>Edit words:</b> click text in the page and type.</li><li><b>Change a picture:</b> click it, then choose the picture button below.</li><li><b>Keep your changes:</b> click Save before leaving.</li></ol>
<div class="toolbar"><span class="label">Text style</span><span class="tools"><button type="button" data-command="bold" title="Bold selected text"><b>B</b></button><button type="button" data-command="italic" title="Italic selected text"><i>I</i></button><button type="button" data-command="underline" title="Underline selected text"><u>U</u></button></span><button type="button" id="insert-image">Add picture at cursor</button><button type="button" id="replace-image" disabled>Replace selected picture</button><input type="file" id="image-file" accept="image/jpeg,image/png,image/webp,image/gif" hidden><button type="button" class="primary" id="save">Save changes</button><a target="_blank" href="../<?= rawurlencode($selected) ?>">View live page ↗</a></div><span id="status" class="status" role="status" aria-live="polite">Click text in the page preview to begin editing.</span></aside>
<section class="preview-panel"><p class="hint">Click words to edit them. Click a picture to select it. To add a picture, click where it should go first.</p><iframe id="preview" title="Editable page preview" src="preview.php?page=<?= rawurlencode($selected) ?>"></iframe></section></div>
<script>
const page=document.querySelector('#page'),frame=document.querySelector('#preview'),status=document.querySelector('#status');let dirty=false;
page.addEventListener('change',()=>{if(!dirty||confirm('You have unsaved edits. Leave this page and discard them?')){dirty=false;location.href='?page='+encodeURIComponent(page.value);}else page.value=<?= json_encode($selected) ?>;});
document.querySelector('#save').addEventListener('click',()=>{status.className='status';status.textContent='Saving your changes…';frame.contentWindow.postMessage({type:'stac-cms-read-content'},location.origin)});
document.querySelectorAll('[data-command]').forEach(button=>button.addEventListener('click',()=>frame.contentWindow.postMessage({type:'stac-cms-command',command:button.dataset.command},location.origin)));
const imageFile=document.querySelector('#image-file'),replaceButton=document.querySelector('#replace-image');let replaceImage=false;
document.querySelector('#insert-image').addEventListener('click',()=>{replaceImage=false;frame.contentWindow.postMessage({type:'stac-cms-store-selection'},location.origin);imageFile.click();});
replaceButton.addEventListener('click',()=>{replaceImage=true;imageFile.click();});
imageFile.addEventListener('change',async()=>{const file=imageFile.files[0];if(!file)return;status.textContent='Uploading image…';try{const form=new FormData();form.append('image',file);const response=await fetch('upload.php',{method:'POST',headers:{'X-CSRF-Token':<?= json_encode($_SESSION['csrf']) ?>},body:form});const result=await response.json();if(!response.ok)throw new Error(result.error||'Image upload failed.');frame.contentWindow.postMessage({type:'stac-cms-image-uploaded',url:result.url,replace:replaceImage},location.origin);status.textContent='Image added. Save changes to publish it.';}catch(error){status.textContent=error.message;}finally{imageFile.value='';}});
window.addEventListener('message',async event=>{if(event.origin!==location.origin)return;if(event.data?.type==='stac-cms-image-state'){replaceButton.disabled=!event.data.selected;replaceButton.textContent=event.data.selected?'Replace this picture':'Click a picture to select it';if(event.data.selected){status.className='status';status.textContent='Picture selected. Choose “Replace this picture” to upload a new one.';}return;}if(event.data?.type==='stac-cms-dirty'){dirty=true;status.className='status dirty';status.textContent='You have unsaved changes. Click Save changes when ready.';return;}if(event.data?.type==='stac-cms-content')try{const response=await fetch('save.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':<?= json_encode($_SESSION['csrf']) ?>},body:JSON.stringify({page:page.value,content:event.data.content})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Could not save changes.');dirty=false;status.className='status';status.textContent='Saved. Your live page is updated.';frame.contentWindow.location.reload();}catch(error){status.className='status error';status.textContent=error.message;}});
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
</script><?php endif; ?></div></html>
